    "setH2": "Indstillinger til et hjemmespil",
    "setP": "Hvert spil i PokerTH er en turnering: alle starter med samme stak og spiller, indtil én spiller har alle jetonerne. Til en afslappet aften giver du en stor startstak, langsomme blinds og lang tid til at handle; til et hurtigt spil før aftensmaden gør du det modsatte. Venner, der kommer for sent, kan se bordet som tilskuere, hvis du tillader det.",
