    "talkP": "På pokerth.net er bordchatten for spillere med en gratis konto; gæster kan spille, men ikke chatte. Mange grupper har simpelthen et tale- eller videoopkald åbent ved siden af bordet.",
    "ownH2": "Kør det selv, derhjemme",
    "ownP": "Du kan også installere PokerTH derhjemme — på en pc, en hjemmeserver eller en Raspberry Pi — til et familiespil, en klub, et kontor eller en skole. PokerTH-serveren og denne webklient er begge gratis og open source: webklienten installeres med en enkelt kommando, med Docker eller på CasaOS, og derefter spiller hver telefon eller tablet på dit wi-fi i browseren med blot et kaldenavn. Invitationslinks virker der præcis som på pokerth.net. Installationsvejledningen ligger på <a href=\"https://github.com/narmod/pokerth-web-client#self-hosting\">GitHub</a>.",
