    "desc": "Starigu senpagan privatan pokertablon kaj sendu unu ligilon aŭ QR-kodon: amikoj aliĝas el ajna telefono aŭ komputilo kaj sidiĝas aŭtomate. Sen konto, sen mono.",
    "ldHeadline": "Kiel ludi pokeron rete kun amikoj, senpage",
    "ldDesc": "Kreu privatan Texas Hold’em-tablon en la retkliento de PokerTH kaj invitu amikojn per ligilo aŭ QR-kodo.",
    "h1": "Ludu pokeron rete kun amikoj, senpage",
