    "privH2": "Tablo, kiu restas privata",
    "privP": "Pasvorto tenas fremdulojn ekstere: ĉiu, kiu aliĝas, eĉ per via ligilo, devas tajpi ĝin. La pasvorto neniam estas parto de la invita ligilo, do plusendita aŭ ekrankopiita ligilo ne malfermas la tablon per si mem. La ligilo nur nomas la tablon kaj la servilon.",
    "setH2": "Agordoj por hejma ludo",
    "setP": "Ĉiu PokerTH-ludo estas turniro: ĉiuj komencas kun la sama stako kaj ludas ĝis unu ludanto havas ĉiujn ĵetonojn. Por trankvila vespero, donu grandan komencan stakon, malrapidajn blindojn kaj longan tempon por agi; por rapida ludo antaŭ la vespermanĝo, faru la malon. Amikoj, kiuj alvenas malfrue, povas spekti la tablon kiel spektantoj, se vi permesas tion.",
    "mixH2": "Telefonoj kaj komputiloj ĉe la sama tablo",
    "mixP": "La retkliento funkcias en ĉiu moderna retumilo, ĉe iPhone, Android, Windows, macOS kaj Linux. Ĉiu povas aldoni ĝin al sia hejmekrano kaj ludi per ĝi kiel per aplikaĵo; la invita ligilo tiam malfermiĝas rekte en ĝi. Ĉirkaŭ vera tablo, la QR-kodo estas la plej rapida eniro: ĉiu ludanto skanas ĝin per sia telefono.",
    "talkH2": "Babili dum la ludo",
    "talkP": "Ĉe pokerth.net la tabla babilejo estas por ludantoj kun senpaga konto; gastoj povas ludi sed ne babili. Multaj grupoj simple tenas voĉan aŭ videan vokon malfermita apud la tablo.",
    "ownH2": "Gastigu ĝin mem, hejme",
    "ownP": "Vi ankaŭ povas instali PokerTH hejme — sur komputilo, hejma servilo aŭ Raspberry Pi — por familia ludo, klubo, oficejo aŭ lernejo. La PokerTH-servilo kaj ĉi tiu retkliento estas ambaŭ senpagaj kaj malfermitkodaj: la retkliento instaliĝas per unu sola komando, per Docker aŭ en CasaOS, kaj ĉiu telefono aŭ tabulkomputilo en via Wi-Fi-reto tiam ludas en sia retumilo per nur kaŝnomo. Invitaj ligiloj funkcias tie same kiel ĉe pokerth.net. La instalgvidilo troviĝas ĉe <a href=\"https://github.com/narmod/pokerth-web-client#self-hosting\">GitHub</a>.",
    "faqH2": "Demandoj",
