        "Ne. Ĉe pokerth.net ili povas aliĝi al Normala tablo kiel gastoj, kaj en LAN aŭ dediĉita servilo kaŝnomo sufiĉas. Senpaga pokerth.net-konto aldonas la babilejon, tablojn nur por registritaj ludantoj kaj Rangigajn ludojn."
