  es: {
    "title": "Jugar al póker con amigos online — gratis, sin descargas | PokerTH",
    "desc": "Monta gratis una mesa de póker privada y envía un enlace o un código QR: tus amigos se unen desde cualquier móvil u ordenador y se sientan solos. Sin cuenta ni dinero.",
    "ldHeadline": "Cómo jugar al póker con amigos online, gratis",
    "ldDesc": "Crea una mesa privada de Texas Hold’em en el cliente web de PokerTH e invita a tus amigos con un enlace o un código QR.",
    "h1": "Juega al póker con amigos online, gratis",
    "lead": "Una noche de póker sin fichas que contar ni cartas que barajar: PokerTH reparte Texas Hold’em en el navegador, para hasta 10 jugadores por mesa. Tú preparas la mesa, envías un enlace y tus amigos se sientan — en un móvil, una tableta o un ordenador, sin descargar nada y sin dinero real de por medio.",
    "stepsH2": "Tu noche de póker en tres pasos",
    "steps": [
      [
        "Abre PokerTH e inicia sesión",
        "Abre este sitio en cualquier navegador. En la red oficial pokerth.net, entra como invitado o con una cuenta gratuita; en tu propia LAN o en un servidor dedicado basta con un apodo. Sin descargas ni dirección de correo."
      ],
      [
        "Crea tu mesa",
        "En el lobby, crea una mesa y deja el tipo de partida <strong>Normal</strong> para que tus amigos puedan unirse como invitados. Elige el número de asientos (hasta 10), la pila inicial, la rapidez con la que suben las ciegas y el tiempo para actuar. Añade una contraseña si la mesa debe seguir siendo privada."
      ],
      [
        "Envía la invitación",
        "En la sala de espera, pulsa <strong>Invitar amigos</strong>. Comparte el enlace por WhatsApp, Telegram, SMS o correo, cópialo o deja que los amigos que están en la misma habitación escaneen el código QR. Quien lo abre inicia sesión y se sienta en tu mesa automáticamente. Cuando estén todos, pulsa <strong>Iniciar partida</strong>."
      ]
    ],
    "privH2": "Una mesa que sigue siendo privada",
    "privP": "Una contraseña deja fuera a los desconocidos: cualquiera que se una, incluso desde tu enlace, tiene que escribirla. La contraseña nunca forma parte del enlace de invitación, así que un enlace reenviado o que aparezca en una captura de pantalla no abre la mesa por sí solo. El enlace solo indica la mesa y el servidor.",
    "setH2": "Ajustes para una partida en casa",
    "setP": "Todas las partidas de PokerTH son torneos: todos empiezan con la misma pila y juegan hasta que un jugador tiene todas las fichas. Para una velada tranquila, pon una pila inicial grande, ciegas lentas y mucho tiempo para actuar; para una partida rápida antes de cenar, haz lo contrario. Los amigos que lleguen tarde pueden ver la mesa como espectadores si lo permites.",
    "mixH2": "Móviles y ordenadores en la misma mesa",
    "mixP": "El cliente web funciona en cualquier navegador moderno, en iPhone, Android, Windows, macOS y Linux. Cualquiera puede añadirlo a su pantalla de inicio y jugar como con una aplicación; el enlace de invitación se abre entonces directamente en ella. Alrededor de una mesa de verdad, el código QR es la forma más rápida de entrar: cada jugador lo escanea con su móvil.",
    "talkH2": "Hablar durante la partida",
    "talkP": "En pokerth.net, el chat de la mesa es para jugadores con cuenta gratuita; los invitados pueden jugar, pero no chatear. Muchos grupos simplemente dejan abierta una llamada de voz o de vídeo junto a la mesa.",
    "ownH2": "Alójalo tú mismo, en casa",
    "ownP": "También puedes instalar PokerTH en casa — en un PC, un servidor doméstico o una Raspberry Pi — para una partida en familia, un club, una oficina o un colegio. El servidor PokerTH y este cliente web son gratuitos y de código abierto: el cliente web se instala con un solo comando, con Docker o en CasaOS, y cualquier móvil o tableta de tu wifi juega entonces en su navegador solo con un apodo. Los enlaces de invitación funcionan allí igual que en pokerth.net. La guía de instalación está en <a href=\"https://github.com/narmod/pokerth-web-client#self-hosting\">GitHub</a>.",
    "faqH2": "Preguntas",
    "faq": [
      [
        "¿Mis amigos necesitan una cuenta?",
        "No. En pokerth.net pueden unirse a una mesa Normal como invitados, y en una LAN o un servidor dedicado basta con un apodo. Una cuenta gratuita de pokerth.net añade el chat, las mesas solo para registrados y las partidas de clasificación."
      ],
      [
        "¿Cuántos jugadores pueden unirse?",
        "Hasta 10 jugadores por mesa, más los espectadores si la mesa los permite."
      ],
      [
        "¿De verdad es gratis?",
        "Sí. PokerTH es software libre y de código abierto, sin anuncios ni compras dentro de la aplicación. Las fichas son solo dinero ficticio: no se puede comprar, vender ni ganar nada."
      ],
      [
        "¿Podemos jugar en el móvil?",
        "Sí, en iPhone y Android igual que en un ordenador, en el navegador o instalado en la pantalla de inicio. Los jugadores con móvil y con ordenador comparten la misma mesa."
      ],
      [
        "¿Y si un amigo abre el enlace cuando la partida ya ha empezado?",
        "La mesa se abre para mirar, así que puede seguir la partida como espectador."
      ]
    ]
  },
