    "desc": "ಉಚಿತವಾಗಿ ಖಾಸಗಿ ಪೋಕರ್ ಟೇಬಲ್ ರಚಿಸಿ, ಒಂದು ಲಿಂಕ್ ಅಥವಾ QR ಕೋಡ್ ಕಳುಹಿಸಿ: ಸ್ನೇಹಿತರು ಯಾವುದೇ ಫೋನ್ ಅಥವಾ ಕಂಪ್ಯೂಟರ್‌ನಿಂದ ಸೇರಿ ತಾನಾಗಿಯೇ ಸೀಟ್ ಪಡೆಯುತ್ತಾರೆ. ಖಾತೆ ಬೇಡ, ಹಣ ಬೇಡ.",
