    "lead": "ಎಣಿಸಲು ಚಿಪ್‌ಗಳಿಲ್ಲದ, ಕಲಸಲು ಕಾರ್ಡ್‌ಗಳಿಲ್ಲದ ಪೋಕರ್ ರಾತ್ರಿ: PokerTH ಬ್ರೌಸರ್‌ನಲ್ಲೇ Texas Hold’em ಹಂಚುತ್ತದೆ, ಒಂದು ಟೇಬಲ್‌ನಲ್ಲಿ 10 ಆಟಗಾರರವರೆಗೆ. ನೀವು ಟೇಬಲ್ ಸಿದ್ಧಪಡಿಸುತ್ತೀರಿ, ಒಂದು ಲಿಂಕ್ ಕಳುಹಿಸುತ್ತೀರಿ, ಮತ್ತು ನಿಮ್ಮ ಸ್ನೇಹಿತರು ಬಂದು ಕೂರುತ್ತಾರೆ — ಫೋನ್, ಟ್ಯಾಬ್ಲೆಟ್ ಅಥವಾ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ, ಏನನ್ನೂ ಡೌನ್‌ಲೋಡ್ ಮಾಡದೆ ಮತ್ತು ನಿಜವಾದ ಹಣವಿಲ್ಲದೆ.",
