    "ownH2": "ਘਰ ਵਿੱਚ ਆਪ ਹੋਸਟ ਕਰੋ",
    "ownP": "ਤੁਸੀਂ PokerTH ਘਰ ਵਿੱਚ ਵੀ ਇੰਸਟਾਲ ਕਰ ਸਕਦੇ ਹੋ — ਪੀਸੀ, ਘਰੇਲੂ ਸਰਵਰ ਜਾਂ Raspberry Pi ’ਤੇ — ਪਰਿਵਾਰਕ ਖੇਡ, ਕਲੱਬ, ਦਫ਼ਤਰ ਜਾਂ ਸਕੂਲ ਲਈ। PokerTH ਸਰਵਰ ਅਤੇ ਇਹ ਵੈੱਬ ਕਲਾਇਂਟ ਦੋਵੇਂ ਮੁਫ਼ਤ ਅਤੇ ਓਪਨ ਸੋਰਸ ਹਨ: ਵੈੱਬ ਕਲਾਇਂਟ ਇੱਕੋ ਕਮਾਂਡ ਨਾਲ ਇੰਸਟਾਲ ਹੁੰਦਾ ਹੈ, Docker ਨਾਲ ਜਾਂ CasaOS ’ਤੇ, ਅਤੇ ਫਿਰ ਤੁਹਾਡੇ Wi-Fi ’ਤੇ ਹਰ ਫੋਨ ਜਾਂ ਟੈਬਲੇਟ ਸਿਰਫ਼ ਇੱਕ ਉਪਨਾਮ ਨਾਲ ਆਪਣੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਖੇਡਦਾ ਹੈ। ਸੱਦਾ ਲਿੰਕ ਉੱਥੇ ਵੀ ਬਿਲਕੁਲ pokerth.net ਵਾਂਗ ਕੰਮ ਕਰਦੇ ਹਨ। ਇੰਸਟਾਲੇਸ਼ਨ ਗਾਈਡ <a href=\"https://github.com/narmod/pokerth-web-client#self-hosting\">GitHub</a> ’ਤੇ ਹੈ।",
