    "setH2": "Inställningar för hemmaspel",
    "setP": "Varje spel i PokerTH är en turnering: alla börjar med samma stack och spelar tills en spelare har alla marker. För en lugn kväll, ge en stor startstack, långsamma mörkar och lång tid att agera; för ett snabbt spel före middagen, gör tvärtom. Vänner som kommer sent kan titta på bordet som åskådare om du tillåter det.",
