    "ownH2": "Kör det själv, hemma",
    "ownP": "Du kan också installera PokerTH hemma — på en PC, en hemserver eller en Raspberry Pi — för familjespel, en klubb, ett kontor eller en skola. PokerTH-servern och den här webbklienten är båda gratis och öppen källkod: webbklienten installeras med ett enda kommando, med Docker eller på CasaOS, och varje mobil eller surfplatta i ditt Wi-Fi spelar sedan i sin webbläsare med bara ett smeknamn. Inbjudningslänkar fungerar där precis som på pokerth.net. Installationsguiden finns på <a href=\"https://github.com/narmod/pokerth-web-client#self-hosting\">GitHub</a>.",
