    "ldDesc": "PokerTH வலை செயலியில் தனிப்பட்ட Texas Hold’em மேசையை உருவாக்கி, இணைப்பு அல்லது QR குறியீடு மூலம் நண்பர்களை அழையுங்கள்.",
